(function()
	_G.pg.base.ship_skin_words[1101010] = {
		feeling1 = "指揮官、静かに。苔類の観察の邪魔です",
		feeling3 = "……この苔は予想以上の早さで生長していますね。ほら、胞子嚢が対照群より37%速く…ん？どうしてそんな目で見てるのですか？私が一気に喋りすぎました？…エヴァーツェンの笑顔が見たいだけ、ですか…？",
		lose = "けが人はいますか？治療を手伝いますよ",
		propose = "…指揮官、このジプソフィラをあなたに。魔法で一番美しい状態のままにしますから枯れる心配はありません……ええ、あなたへの愛のように、枯れることも消えることもなく、永遠にこのままですよ",
		expedition = "委託組が戻ってきました。今回の目的地は…研究し甲斐がありそうです。指揮官、今度私にも行かせてください",
		win_mvp = "勝ちましたね。良かったです",
		home = "戻ってきて早々もうお仕事です？……魔法で疲れを解消してあげますから、ここに座ってください",
		mission = "指揮官、任務を忘れずにこなすように。…先に魔法で疲れを取っておきましょうか？",
		touch2 = "……？！やめてください…恥ずかしいですから…",
		voice_key_2 = -1,
		skill = "甦って",
		drop_descrip = "アドミラーレン級駆逐艦-エヴァーツェン",
		mail = "メールが来ています。忘れずにご確認を",
